<script>
const tabData = {
  "Rat Caging": {
    title: "Rat Caging",
    description:
      "The Innocage® IVC Rat Caging System offers the convenience of quick access to the water bottle, by housing it in a secure cavity built into the cage lid. The cage set offers an IVC or Static lid option and utilizes a universal bottom, water bottle, and a stainless steel wirebar.",
    imageSrc:
      "https://inno.myvoladolabs.com/wp-content/uploads/2026/06/Rat-Caging.png",
    bottomUrl: "https://inno.myvoladolabs.com/rat-caging-btm",
  },

  "Tall Rat Caging": {
    title: "Tall Rat Caging",
    description:
      'The Innocage® Tall IVC Rat system offers the benefit of more headroom, providing 9" (22.9cm). The Tall Rat caging uses a Tall Rat cage lid, stainless steel wire bar, an 850 mL water bottle, and a universal rat cage bottom.',
    imageSrc:
      "https://inno.myvoladolabs.com/wp-content/uploads/2026/06/Tall-Rat-Caging.png",
    bottomUrl: "https://inno.myvoladolabs.com/rat-caging-btm",
  },

  "Tall Rat XL Caging": {
    title: "Tall Rat XL Caging",
    description:
      'The Innocage® Tall IVC Rat XL system offers larger living space and floor area, providing 325.8 in² (2080.6 cm²) of floor space and 9" (22.9cm) of headroom. The cage set uses a Tall Rat XL cage lid, stainless steel wire bars, 850 mL water bottles, and the Innocage® Tall Rat XL cage bottom.',
    imageSrc:
      "https://inno.myvoladolabs.com/wp-content/uploads/2026/06/Tall-Rat-XL-Caging.png",
    bottomUrl: "https://inno.myvoladolabs.com/rat-caging-btm/?tab=R-BTM-XL",
  }
};

const tabs = document.querySelectorAll(".tab");
const titleEl = document.getElementById("dynamic-title");
const descriptionEl = document.getElementById("dynamic-description");
const imageEl = document.getElementById("dynamic-image");
let currentBottomUrl = "";

function updateContent(tabId) {
  const data = tabData[tabId];
  if (!data) return;
  currentBottomUrl = data.bottomUrl || "";

  // simple fade effect
  const container = document.getElementById("dynamic-content-area");
  container.style.opacity = 0;
  imageEl.style.opacity = 0;

  setTimeout(() => {
    titleEl.textContent = data.title;
    descriptionEl.textContent = data.description;

    imageEl.src = data.imageSrc;

    imageEl.onload = () => {
      imageEl.style.opacity = 1;
    };

    container.style.opacity = 1;

  }, 200);
}

// tab click
tabs.forEach(tab => {
  tab.addEventListener("click", () => {
    if (tab.classList.contains("active")) return;

    tabs.forEach(t => t.classList.remove("active"));
    tab.classList.add("active");

    updateContent(tab.getAttribute("data-id"));
  });
});

const exploreBtn = document.getElementById("explore-bottom-btn");
if (exploreBtn) {
  exploreBtn.addEventListener("click", () => {
    if (currentBottomUrl) window.location.href = currentBottomUrl;
  });
}

// init
updateContent("Rat Caging");
